# Append females
fem_path = os.path.join('tools', 'data_females_extra.py')
with open(fem_path, 'r', encoding='utf-8') as f:
    fc = f.read()
idx = fc.rfind("]")
f_str = ""
for item in females_batch:
    f_str += f"    {repr(item)},\n"
fc_new = fc[:idx] + f_str + "]\n"
with open(fem_path, 'w', encoding='utf-8') as f:
    f.write(fc_new)
print(f"Appended {len(females_batch)} females to {fem_path}")

